const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Atlanta urban area
  const atlanta = ee.Geometry.Point([-84.388, 33.749]).buffer(15000); // 15km radius for urban area

  // Define time periods
  const july2013Start = '2013-07-01';
  const july2013End = '2013-07-31';
  const dec2013Start = '2013-12-01';
  const dec2013End = '2013-12-31';

  // Load VIIRS Nighttime Lights monthly data
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

  // Get July 2013 data
  const july2013 = viirs
    .filterDate(july2013Start, july2013End)
    .filterBounds(atlanta);

  const julySize = july2013.size().getInfo();
  console.log('July 2013 images:', julySize);

  if (julySize === 0) {
    console.log('No data for July 2013.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get December 2013 data
  const dec2013 = viirs
    .filterDate(dec2013Start, dec2013End)
    .filterBounds(atlanta);

  const decSize = dec2013.size().getInfo();
  console.log('December 2013 images:', decSize);

  if (decSize === 0) {
    console.log('No data for December 2013.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get mean images for each period
  const julyImage = july2013.select('avg_rad').mean();
  const decImage = dec2013.select('avg_rad').mean();

  // Check pixel counts
  const julyCount = julyImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: atlanta,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log('July valid pixels:', julyCount);

  if (julyCount === 0) {
    console.log('No valid pixels for July 2013.');
    console.log('<answer>C2</answer>');
    return;
  }

  const decCount = decImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: atlanta,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log('December valid pixels:', decCount);

  if (decCount === 0) {
    console.log('No valid pixels for December 2013.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate mean nighttime light intensity
  const julyMean = julyImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: atlanta,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const decMean = decImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: atlanta,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log('July 2013 mean light intensity:', julyMean);
  console.log('December 2013 mean light intensity:', decMean);

  // Validate results
  if (julyMean === null || decMean === null || 
      isNaN(julyMean) || isNaN(decMean) ||
      julyMean < 0 || decMean < 0) {
    console.log('Invalid calculation results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare December vs July
  const increase = decMean - julyMean;
  console.log('Change (Dec - July):', increase.toFixed(4));

  if (decMean > julyMean) {
    console.log('December nighttime lights increased compared to July.');
    console.log('<answer>A</answer>');
  } else {
    console.log('December nighttime lights did not increase compared to July.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
